#include "../models/conservative_beam/ConservativeBeam.cpp"
#include <sofa/component/statecontainer/MechanicalObject.h>
#include <iostream>
using namespace regrip_beam;
void require(bool b,const char*s){if(!b)throw std::runtime_error(s);}
int main(){try{auto state=sofa::core::objectmodel::New<sofa::component::statecontainer::MechanicalObject<Types>>();state->resize(3);Base::VecCoord x(3);for(auto&p:x)p.getOrientation()={0,0,0,1};x[1].getCenter()={10,0,0};state->write(sofa::core::vec_id::write_access::restPosition)->setValue(x);state->write(sofa::core::vec_id::write_access::position)->setValue(x);auto field=sofa::core::objectmodel::New<ConservativeBeam>(state.get());field->edges.setValue({0,1});field->init();auto original=field->values(x)[0];x[2].getCenter()[0]=12345;auto ignored=field->values(x)[0];require(ignored.force==original.force&&ignored.jacobian==original.jacobian,"unused object pose cache independence");x[1].getCenter()[0]+=.02;auto changed=field->values(x)[0];require(std::abs(changed.force[6]+.002)<1e-12,"endpoint cache invalidation");field->EA.setValue(2);auto material=field->values(x)[0];require(std::abs(material.force[6]+.004)<1e-12,"material cache invalidation");state->write(sofa::core::vec_id::write_access::position)->setValue(x);field->rayleighStiffness.setValue(.3);Base::DataVecDeriv dx,df;Base::VecDeriv v(3);for(auto&a:v)for(int j=0;j<6;++j)a[j]=.01*(j+1);dx.setValue(v);
 for(double factor:{0.,2.5,-.25}){df.setValue(Base::VecDeriv(3));sofa::core::MechanicalParams mp;mp.setKFactor(factor);mp.setBFactor(.4);field->addDForce(&mp,df,dx);for(int i=0;i<12;++i){double expected=0;for(int j=0;j<12;++j)expected+=(factor+.12)*material.jacobian[12*i+j]*v[j/6][j%6];require(std::abs(expected-df.getValue()[i/6][i%6])<1e-12,"Rayleigh/kFactor including negative/zero");}}
 bool invalid=false;auto bad=x;bad[1].getOrientation()={0,0,0,0};try{field->values(bad);}catch(const std::invalid_argument&){invalid=true;}require(invalid,"nonunit quaternion rejected");require(field->values(x)[0].force==material.force,"failure cannot poison cache");field->EA.setValue(-1);invalid=false;try{field->values(x);}catch(const std::invalid_argument&){invalid=true;}require(invalid,"negative stiffness rejected");field->EA.setValue(2);field->edges.setValue({1,0});invalid=false;try{field->values(x);}catch(const std::invalid_argument&){invalid=true;}require(invalid,"runtime topology change rejected");std::cout<<"PASS extra API cache/material/unusedobject/error atomicity/Rayleigh/kFactor\n";
}catch(const std::exception&e){std::cerr<<"FAIL "<<e.what()<<'\n';return 1;}}
